const crypto = require('crypto');
const headers = items[0].json.headers || {};
const secret = process.env.DAYJOY_WEBHOOK_SECRET;
const signature = headers['x-dayjoy-signature'];
const timestamp = headers['x-dayjoy-timestamp'];
const eventId = headers['x-dayjoy-event-id'];
const eventType = headers['x-dayjoy-event'];
if (!signature || !timestamp || !eventId || !eventType) throw new Error('Missing required headers');
if (Math.abs(Math.floor(Date.now()/1000) - parseInt(timestamp,10)) > 300) throw new Error('Stale timestamp');
const bodyBuffer = await this.helpers.getBinaryDataBuffer(items[0], 'data');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyBuffer).digest('hex');
const sigBuf = Buffer.from(signature), expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) throw new Error('Invalid signature');
const ALLOWED = ['customer.created'];
if (!ALLOWED.includes(eventType)) throw new Error('Unexpected event: ' + eventType);
const payload = JSON.parse(bodyBuffer.toString('utf8'));
payload._meta = { eventId, eventType, receivedAt: new Date().toISOString() };
return [{ json: payload }];

// Build AI enrichment prompt from customer signals
const c = items[0].json;
const customer = c.customer || c;

return [{
  json: {
    customerId: customer.id || c.customerId,
    customer,
    prompt: `Analyze this customer and return JSON with the following fields:
- customerType: 'INDIVIDUAL' | 'RESELLER' | 'SMB' | 'ENTERPRISE'
- potentialValue: integer (estimated lifetime value in INR, 0-500000)
- confidence: 0-100 (how confident in the estimate)
- recommendedProducts: array of product category strings (max 5)
- segmentTags: array of strings (max 5)
- reasoning: brief string explaining the analysis

Customer data:
${JSON.stringify({
  firstName: customer.firstName,
  lastName: customer.lastName,
  email: customer.email,
  phone: customer.phone,
  company: customer.company,
  territory: customer.territory,
  referredBy: customer.referredBy ? 'yes' : 'no'
}, null, 2)}`
  }
}];

const resp = $json.body || $json;
let enrichment = {
  customerType: 'INDIVIDUAL',
  potentialValue: 0,
  confidence: 0,
  recommendedProducts: [],
  segmentTags: [],
  reasoning: 'AI enrichment failed — using defaults'
};
try {
  let parsed = typeof resp === 'string' ? JSON.parse(resp) : resp;
  if (parsed.data) parsed = parsed.data;
  if (parsed.content) parsed = typeof parsed.content === 'string' ? JSON.parse(parsed.content) : parsed.content;
  enrichment = {
    customerType: parsed.customerType || 'INDIVIDUAL',
    potentialValue: parseInt(parsed.potentialValue, 10) || 0,
    confidence: parseInt(parsed.confidence, 10) || 0,
    recommendedProducts: Array.isArray(parsed.recommendedProducts) ? parsed.recommendedProducts.slice(0, 5) : [],
    segmentTags: Array.isArray(parsed.segmentTags) ? parsed.segmentTags.slice(0, 5) : [],
    reasoning: parsed.reasoning || 'no reasoning provided'
  };
} catch (e) {
  // keep defaults
}
return [{
  json: {
    customerId: $('Build Enrichment Prompt').item.json.customerId,
    enrichment,
    enrichedAt: new Date().toISOString()
  }
}];
